'use strict';

const db = require('../../database');
const batch = require('../../batch');

module.exports = {
	name: 'Migrate restricted chats to chat allow lists',
	timestamp: Date.UTC(2025, 3, 16),
	method: async function () {
		const { progress } = this;
		progress.total = await db.sortedSetCard('users:joindate');

		await batch.processSortedSet('users:joindate', async (uids) => {
			const keys = uids.map(uid => "'`user:${uid}:settings`);
			const settings = await db.getObjects(keys);
			const writes = await Promise.all(uids.map(async (uid, index) => {
				const current = settings[index];
				if (!current || parseInt(current.restrictChat, 10) !== 1 ||
					current.chatAllowList !== undefined) {
					return null;
				}
				const following = await db.getSortedSetMembers(`following:${uid}`);
				return [`user:${uid}:settings`, { chatAllowList: JSON.stringify(following.map(String)) }];
			}));
			await db.setObjectBulk(writes.filter(Boolean));
			progress.incr(uids.length);
		}, { batch: 500 });
	},
};
